package earth.terrarium.pastel.data.lang.guidebook.equipment;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class AzureDikeEntry {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.azure_dike_equipment.name", "Azure Dike Equipment");
		provider.add("book.pastel.guidebook.azure_dike_equipment.page0.text", "The results of combining [Azurite](entry://general/azurite) with the protective properties of [Blue Pigment](entry://general/pigment@blue) really piqued my interest. The material seemed to surround itself with a transparent aura that took some effort to penetrate when I reached for the lump again.\\\n\\\n*This is going to be interesting...*");
		provider.add("book.pastel.guidebook.azure_dike_equipment.page1.text", "A magical aura surrounding my body, shielding me from incoming damage.\\\nSlowly but steadily recharges up to a certain amount.\\\n\\\nEach piece of [#](2c2e8e)Azure Dike[#]() equipment increases the maximum amount of protection.");
		provider.add("book.pastel.guidebook.azure_dike_equipment.page1.title", "Azure Dike");
		provider.add("book.pastel.guidebook.azure_dike_equipment.page2.text", "- Grants [#](495b24)6[#]() units of [#](2c2e8e)Azure Dike[#]()\n- Increases [#](2c2e8e)Azure Dike[#]() charging");
		provider.add("book.pastel.guidebook.azure_dike_equipment.page3.text", "- Grants [#](495b24)8[#]() units of [#](2c2e8e)Azure Dike[#]()\n- Increases [#](2c2e8e)Azure Dike[#]() recovery after a hit, making it recharge quicker");
		provider.add("book.pastel.guidebook.azure_dike_equipment.page4.text", "Infusing it with [Blue Ink](entry://ink/ink) in a [Color Picker](entry://ink/color_picker) increases the amount of [#](2c2e8e)Azure Dike[#]() provided.\\\n\\\nCheap at first, but the required ink per level increases exponentially.");
	}
}
